import itertools

def solve_k(k):
    perms = list(itertools.permutations(range(1, k + 1)))
    n = len(perms)
    adj = [set() for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            close = True
            for p1, p2 in zip(perms[i], perms[j]):
                if abs(p1 - p2) > 1:
                    close = False
                    break
            if close:
                adj[i].add(j)
                adj[j].add(i)

    memo = {}
    def max_indep(nodes_tuple):
        if not nodes_tuple:
            return 0
        if nodes_tuple in memo:
            return memo[nodes_tuple]

        v = nodes_tuple[0]

        # Option 1: exclude v
        res1 = max_indep(nodes_tuple[1:])

        # Option 2: include v
        remaining_nodes = tuple(n for n in nodes_tuple[1:] if n not in adj[v])
        res2 = 1 + max_indep(remaining_nodes)

        memo[nodes_tuple] = max(res1, res2)
        return memo[nodes_tuple]

    return max_indep(tuple(range(n)))

for k in range(2, 6):
    print(f"k={k}: {solve_k(k)}")

